input.command:
cd /bench/home/work; for t in User Memo Attachment Reaction Inbox IdentityProvider UserSetting Activity WebhookMessage MemoRelation; do
  # find files outside store/ that reference store.<Type> (word boundary, not as substring like store.UserSetting when counting User)
  files=$(grep -rlE "\bstore\.$t\b" --include=*.go . | grep -v node_modules | grep -vE "^\./store/" | grep -viE "_test\.go");
  if [ -n "$files" ]; then
    pkgs=$(echo "$files" | xargs -n1 dirname | sort -u);
    cnt=$(echo "$pkgs" | grep -c .);
    echo "=== store.$t : $cnt packages ===";
    echo "$pkgs";
  else
    echo "=== store.$t : 0 packages ===";
  fi
done

cd /bench/home/work; echo "Excluding the ENTIRE store/ data layer (store/, store/db/*), and tests:"; for t in User Memo Attachment Inbox Reaction MemoRelation IdentityProvider UserSetting; do
  files=$(grep -rlE "\bstore\.$t\b" --include=*.go . 2>/dev/null | sed 's|^\./||' | grep -v node_modules | grep -vE "^store/" | grep -viE "_test\.go");
  pkgs=$(echo "$files" | grep -v '^$' | xargs -n1 dirname 2>/dev/null | sort -u);
  cnt=$(echo "$pkgs" | grep -c .);
  echo "store.$t : $cnt pkgs -> $(echo $pkgs | tr '\n' ' ')";
done

